import { createServerFn } from '@tanstack/react-start'
import { defaultProjectData, type ProjectData, type ProjectView } from '#/lib/project'
import { projectStore } from './projects.server'

function obj(value: unknown, field = 'vstup'): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Neplatný ${field}`)
  return value as Record<string, unknown>
}

// Upper bound against abuse only; the store trims and cuts names/labels to their real limits.
function str(value: unknown, field: string, max = 1000) {
  if (typeof value !== 'string' || value.length > max) throw new Error(`${field}: očakávaný text`)
  return value
}

function int(value: unknown, field: string) {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) throw new Error(`${field}: očakávané číslo`)
  return value
}

// Validator parameters are typed for callers (the client gets compile-time checked inputs); values are still checked
// at runtime as untrusted input.
const id = (o: Record<string, unknown>) => str(o.id, 'id', 64)
const idInput = (d: { id: string }) => ({ id: id(obj(d)) })
const snapshotInput = (d: { id: string; snapshotId: number }) => {
  const o = obj(d)
  return { id: id(o), snapshotId: int(o.snapshotId, 'snapshotId') }
}

export const listProjectsFn = createServerFn().handler(() => projectStore().listProjects())

export const getProjectFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => projectStore().getProject(data.id))

export const createProjectFn = createServerFn({ method: 'POST' })
  .validator((d: { name: string; data?: ProjectData }) => {
    const o = obj(d)
    return { name: str(o.name, 'Názov'), data: o.data === undefined ? defaultProjectData() : obj(o.data, 'projekt') }
  })
  .handler(({ data }) => projectStore().createProject(data.name, data.data))

export const saveProjectFn = createServerFn({ method: 'POST' })
  .validator((d: { id: string; data: ProjectData; baseRevision: number }) => {
    const o = obj(d)
    return { id: id(o), data: obj(o.data, 'projekt'), baseRevision: int(o.baseRevision, 'baseRevision') }
  })
  .handler(({ data }) => projectStore().saveProject(data.id, data.data, data.baseRevision))

// Saves the per-project view state (LL simulation step/speed); never bumps the revision or creates snapshots.
export const saveViewStateFn = createServerFn({ method: 'POST' })
  .validator((d: { id: string; view: ProjectView }) => {
    const o = obj(d)
    return { id: id(o), view: obj(o.view, 'stav zobrazenia') }
  })
  .handler(({ data }) => projectStore().saveViewState(data.id, data.view))

export const importIntoProjectFn = createServerFn({ method: 'POST' })
  .validator((d: { id: string; data: ProjectData; label: string }) => {
    const o = obj(d)
    return { id: id(o), data: obj(o.data, 'projekt'), label: str(o.label, 'Popis') }
  })
  .handler(({ data }) => projectStore().replaceProjectData(data.id, data.data, data.label))

export const renameProjectFn = createServerFn({ method: 'POST' })
  .validator((d: { id: string; name: string }) => ({ ...idInput(d), name: str(obj(d).name, 'Názov') }))
  .handler(({ data }) => projectStore().renameProject(data.id, data.name))

export const deleteProjectFn = createServerFn({ method: 'POST' })
  .validator(idInput)
  .handler(({ data }) => projectStore().deleteProject(data.id))

export const duplicateProjectFn = createServerFn({ method: 'POST' })
  .validator(idInput)
  .handler(({ data }) => projectStore().duplicateProject(data.id))

export const listSnapshotsFn = createServerFn()
  .validator(idInput)
  .handler(({ data }) => projectStore().listSnapshots(data.id))

export const createSnapshotFn = createServerFn({ method: 'POST' })
  .validator((d: { id: string; label: string }) => ({ ...idInput(d), label: str(obj(d).label, 'Popis') }))
  .handler(({ data }) => projectStore().createSnapshot(data.id, data.label))

export const restoreSnapshotFn = createServerFn({ method: 'POST' })
  .validator(snapshotInput)
  .handler(({ data }) => projectStore().restoreSnapshot(data.id, data.snapshotId))

export const deleteSnapshotFn = createServerFn({ method: 'POST' })
  .validator(snapshotInput)
  .handler(({ data }) => projectStore().deleteSnapshot(data.id, data.snapshotId))
